import rq
import django_rq
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def cancel_pipeline_job(request, job_id):
    conn = django_rq.get_connection('default')
    try:
        job = rq.job.Job.fetch(job_id, connection=conn)
    except rq.exceptions.NoSuchJobError:
        return Response({'error': 'Job does not exist'}, status=status.HTTP_404_NOT_FOUND)

    # Validate that the job metadata specifies an organization matching the user's
    job_org_id = job.meta.get('organization_id')
    if not job_org_id or str(job_org_id) != str(request.user.organization_id):
        return Response({'error': 'Access denied to this job'}, status=status.HTTP_403_FORBIDDEN)

    job.cancel()
    job.delete()
    return Response({'status': 'cancelled', 'job_id': job_id})
